  return `${channel}:${user.id}:${category}`;
}

// A throttle policy returns a decision to stop evaluation, or undefined to
// defer to the next policy in the channel's list.
function hourlyLimit(user, message, options, context) {
  if (options.force || message.priority === 'urgent') {
    return undefined;
  }

  const key = throttleKey(context.channel, user, message);
  const now = context.now().getTime();
  const records = (context.throttleStore.get(key) || []).filter(ts => now - ts < MS_PER_HOUR);

  if (records.length >= context.maxPerHour) {
    return {
      throttled: true,
      reason: `${context.channel} hourly limit reached`,
      retryAt: new Date(records[0] + MS_PER_HOUR).toISOString()
    };
  }

  return undefined;
}

function requireMarketingOptIn(optInField, reason) {
  return function marketingOptIn(user, message) {
    if (message.category === 'marketing' && !user[optInField]) {
      return { throttled: true, reason, retryAt: null };
    }
    return undefined;
  };
}

function evaluateThrottle(policies, user, message, options, context) {
  for (const policy of policies) {
    const decision = policy(user, message, options, context);
    if (decision) {
      return decision;
    }
  }
  return { throttled: false };
}

function recordDelivery(context, user, message) {
  const key = throttleKey(context.channel, user, message);
  const records = context.throttleStore.get(key) || [];
  records.push(context.now().getTime());
  context.throttleStore.set(key, records);
}

module.exports = {
  MS_PER_HOUR,
  hourlyLimit,
  requireMarketingOptIn,
  evaluateThrottle,
  recordDelivery
};

